xpath.script:
(function(){
  function init(){
    var sel=document.getElementById('pkPriceList');
    var precio=document.querySelector('input[name="price"]');
    if(!sel||!precio) return;
    var pres=document.querySelector('select[name="presentation"]');
    var talla=document.querySelector('select[name="size_grade_id"]');
    function fill(){
      var pl=sel.value;
      if(!pl){ precio.readOnly=false; precio.style.background=''; return; }
      precio.readOnly=true; precio.style.background='#eef2f5';
      var p=pres?pres.value:'', t=talla?talla.value:'';
      if(!p||!t){ return; }
      fetch('/marketplace/precio-de-lista',{method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({jsonrpc:'2.0',method:'call',
          params:{price_list_id:pl,presentation:p,size_grade_id:t}})})
        .then(function(r){return r.json();}).then(function(d){
          var r=(d&&d.result)||{}; if(r.precio!=null){ precio.value=r.precio.toFixed(2); }
        }).catch(function(){});
    }
    sel.addEventListener('change', fill);
    if(pres) pres.addEventListener('change', fill);
    if(talla) talla.addEventListener('change', fill);
    fill();
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}
})();

(function(){
  function init(){
    var pres  = document.querySelector('select[name="presentation"]');
    var talla = document.querySelector('select[name="size_grade_id"]');
    var precio = document.querySelector('input[name="price"]');
    var caja  = document.getElementById('pk_sugerencia');
    if(!pres || !talla || !precio || !caja) return;
    var txt = caja.querySelector('.pk-sug-txt');
    var usar = caja.querySelector('.pk-sug-usar');
    var ultimo = null;

    function mostrar(html, valor){
      txt.innerHTML = html;
      caja.style.display = 'block';
      ultimo = valor;
      usar.style.display = valor ? 'inline-block' : 'none';
    }
    function consultar(){
      var p = pres.value, t = talla.value;
      if(!p || !t){ caja.style.display = 'none'; return; }
      fetch('/marketplace/precio-sugerido', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc:'2.0', method:'call',
                              params:{presentation: p, size_grade_id: t}})
      }).then(function(r){ return r.json(); }).then(function(d){
        var r = (d && d.result) || {};
        if(r.precio){
          var u = r.uom === 'kg' ? 'Kg' : 'Lb';
          var extra = r.cuantas > 1 ? (' · ' + r.cuantas + ' empacadoras cotizan esta talla') : '';
          mostrar('<strong>' + r.empacadora + '</strong> te paga <strong>$' +
                  r.precio.toFixed(2) + ' / ' + u + '</strong> por esta talla' + extra,
                  r.precio);
        } else if(r.sin_precio){
          mostrar('Ninguna de tus ' + r.listas + ' lista(s) vigente(s) cotiza esta talla.', null);
        } else if(r.sin_listas){
          caja.style.display = 'none';
        } else {
          caja.style.display = 'none';
        }
      }).catch(function(){ caja.style.display = 'none'; });
    }
    // Se rellena solo si el campo está vacío: no se pisa un precio que el
    // camaronero ya escribió a mano.
    usar.addEventListener('click', function(){
      if(ultimo){ precio.value = ultimo.toFixed(2); precio.focus(); }
    });
    pres.addEventListener('change', consultar);
    talla.addEventListener('change', consultar);
    consultar();
  }
  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', init); }
  else { init(); }
})();
